	templates = {
		{ "📋 Daily Quests\nClear {number1} dungeon(s)  ✅ tap to claim!\nSucceed at upgrading {number2} times  ✅ tap to claim!\nSpend {number3} stat points (T key / Stats button)  ✅ tap to claim!\nOpen the pet window (P key / Growth > Pet)  ✅ tap to claim!", "📋 Misiones diarias\nCompleta {number1} mazmorras ✅ ¡toca para reclamar!\n¡Ten éxito al mejorar {number2} veces ✅ toca para reclamar!\nGasta {number3} puntos de estadísticas (tecla T / botón de estadísticas) ✅ ¡toca para reclamar!\nAbre la ventana de mascotas (tecla P / Crecimiento > Mascota) ✅ ¡toca para reclamar!" },
		{ "Flame Temple\n\n🔥 Charges and explosions! Charging enemies are tough and fast, and the Flame Lord rains down meteors and shockwaves (advanced)\n\nSurvive {number1}s + Boss\nRecommended Power {number2}", "Templo de las llamas\n\n🔥 ¡Cargas y explosiones! Los enemigos que cargan son difíciles y rápidos, y el Señor de las Llamas lanza meteoritos y ondas de choque (avanzado)\n\nSobrevive {number1} segundos + Jefe\nPoder recomendado {number2}" },
		{ "💡 Set gear drops in field zones at a set rate. Wear {number1}-{number2} pieces of the same zone's set and effects you unlocked with gold get boosted to Lv.{number3}-{number4} Preview effects in the J key Codex", "💡 Establece la tasa de caída de equipamiento en las zonas de campo a un ritmo predefinido. Usa {number1}-{number2} piezas del conjunto de la misma zona y los efectos que desbloqueaste con oro se mejoran al nivel {number3}-{number4}. Previsualiza los efectos en el Codex de la tecla J." },
		{ ": if no Legendary or better drops in {number1} pulls, the {number2}th pull is a guaranteed Legendary. If no Mythic drops in {number3} pulls, the {number4}th pull is a guaranteed Mythic. The counts are saved.", ": si no sale Legendario o mejor en {number1} tiradas, la tirada {number2} es Legendario garantizado. Si no sale Mítico en {number3} tiradas, la tirada {number4} es Mítico garantizado. Los contadores se guardan." },
		{ "💡 Every player faces the same bosses, so gear and level decide your score. Dash through shots for NEAR MISS, and aim at the yellow weak-spot orb (x{number1} damage).", "💡 Todos los jugadores enfrentan a los mismos jefes, por lo que el equipo y el nivel deciden tu puntuación. Esquiva los disparos para conseguir un casi impacto y apunta al orbe de punto débil amarillo (x{number1} de daño)." },
		{ "A new dungeon theme can now appear (Ice Fortress, Level {number1}+). Pick a depth: deeper means better drop odds and tougher bosses. A marker now points to the gate.", "Un nuevo tema de mazmorra puede aparecer ahora (Fortaleza de hielo, nivel {number1}+). Elige una profundidad: una mayor profundidad significa mejores probabilidades de botín y jefes más difíciles. Un marcador ahora apunta a la puerta." },
		{ "Aim at the yellow orb circling the boss with your mouse and click it to expose a weak spot: x{number1} damage taken for {number2}s! + Dead Eye gauge (auto-attack won't work)", "Apunta con el ratón al orbe amarillo que rodea al jefe y haz clic en él para exponer un punto débil: ¡x{number1} de daño durante {number2} segundos! + Indicador de Ojo Muerto (los ataques automáticos no funcionarán)" },
		{ "A boss arrives every {number1}~{number2}s, and they pile up if you don't take them down. Score = seconds survived x damage dealt. The run ends when you fall (max {number3} min).", "Un jefe llega cada {number1}~{number2} segundos, y se acumulan si no los eliminas. Puntuación = segundos sobrevividos x daño infligido. La partida termina cuando caes (máximo {number3} minutos)." },
		{ "Good to know for the field: press Q to burst forward in your moving direction ({number1} in a row, recharges every {number2}s). Narrowly dodge enemy shots for a bonus!", "Es bueno saberlo para el campo: presiona Q para impulsarte hacia adelante en tu dirección de movimiento ({number1} veces seguidas, se recarga cada {number2} segundos). ¡Esquiva con precisión los disparos enemigos para obtener una bonificación!" },
		{ "Double Shot: each time you shoot, there's a chance the same shot fires again {number1}s later (same power). With the max {number2} points, about {number3}%.", "Disparo doble: cada vez que disparas, hay una probabilidad de que el mismo disparo se repita {number1} segundos después (con la misma potencia). Con el máximo de {number2} puntos, aproximadamente {number3}%." },
		{ "🌟 A golden FEVER portal opened next to the fallen Colossus! Grab your loot, then press E at the portal within {number1} seconds!", "🌟 ¡Se abrió un portal Fiebre dorado junto al Coloso caído! Recoge tu botín y pulsa E en el portal en {number1} segundos." },
		{ "🔒 Zone {number1} · Wasteland Sealed\nZone {number2} monsters {number3} / {number4} defeated · Lord 👑 Not defeated\nOpen to earn the 🏚 Will of the Ruins set!", "🔒 Zona {number1} · Tierra baldía sellada\nZona {number2}: monstruos {number3} / {number4} derrotados · Señor 👑 No derrotado\n¡Abre para ganar el conjunto de la Voluntad de las Ruinas!" },
		{ "Legendary Blacksmith   Title 『Legendary Blacksmith』\nUpgrade all the way to the last weapon (level {number1})\n{number2} / {number3}   Reward: 🎫 {number4}", "Título de herrero legendario\nMejora hasta la última arma (nivel {number1})\n{number2} / {number3} Recompensa: 🎫 {number4}" },
		{ "🔒 Zone {number1} · Desert Sealed\nZone {number2} monsters {number3} / {number4} defeated · Lord 👑 Not defeated\nOpen to earn the 🏜 Desert Sun set!", "🔒 Zona {number1} · Desierto sellado\nZona {number2}: monstruos {number3} / {number4} derrotados · Señor 👑 No derrotado\nAbre para ganar el conjunto de sol del desierto 🏜!" },
		{ "💰 Not enough Gold. ({number1} needed) Earn Gold at the Training Dummy / field hunting / dungeons / Boss Rush rewards", "💰 Oro insuficiente. (se necesitan {number1}) Gana oro con el muñeco de entrenamiento / la caza en el campo / las mazmorras / las recompensas del Boss Rush" },
		{ "Legend Wielder   Title 『Legend Wielder』\nReach weapon upgrade level {number1} (about the {number2}th weapon)\n{number3} / {number4}   Reward: 🎫 {number5}", "Título de portador de leyendas\nAlcanza el nivel de mejora de armas {number1} (aproximadamente la {number2}ª arma)\n{number3} / {number4} Recompensa: 🎫 {number5}" },
		{ "Tier rewards by total damage dealt (gold · tickets · time skip):\n🥉 {number1}+   🥈 {number2}M+   🥇 {number3}M+   💠 {number4}M+   💎 {number5}M+   👑 {number6}M+", "Recompensas de nivel según el daño total infligido (oro · boletos · salto de tiempo):\n🥉 {number1}+   🥈 {number2}M+   🥇 {number3}M+   💠 {number4}M+   💎 {number5}M+   👑 {number6}M+" },
		{ "Zone {number1} · Wasteland\n🏚 Ruined Fortress Gate · Rec. ⚡{number2}\nDanger ☠☠☠\n🏚 New set from here: Will of the Ruins Set", "Zona {number1} · Tierra baldía\n🏚 Puerta de la fortaleza en ruinas · Rec. ⚡{number2}\nPeligro ☠☠☠\n🏚 Nuevo conjunto a partir de aquí: Conjunto de la voluntad de las ruinas" },
		{ "🎖 Lv.{number1}  {number2} / {number3} XP\n💰 {number4} G   🎫 {number5}\n🔑{number6} (Free today {number7}/{number8})\n⚡ Power {number9}\n⚔ Rocket Launcher · Rusty Era +{number10}\n📍 Field (best: Zone {number11})", "🎖 Nivel {number1} {number2} / {number3} XP\n💰 {number4} G 🎫 {number5}\n🔑{number6} (Gratis hoy {number7}/{number8})\n⚡ Poder {number9}\n⚔ Lanzador de cohetes · Era oxidada +{number10}\n📍 Campo (mejor: Zona {number11})" },
		{ "🎯 Bounty! An elite pack appeared off the main road in Zone {number1}. Defeat all {number2} within {number3} seconds for a reward!", "🎯 ¡Recompensa! Apareció una manada de élites fuera del camino principal en la zona {number1}. ¡Derrota a los {number2} en {number3} segundos!" },
		{ "Defeat as many monsters as you can in {number1} seconds. Rewards x{number2}, and keep your combo going for up to x{number3} more", "Derrota tantos monstruos como puedas en {number1} segundos. Recompensas x{number2}, y mantén tu combo para hasta x{number3} más" },
		{ "🎖 Lv.{number1}  {number2} / {number3} XP\n💰 {number4} G   🎫 {number5}\n🔑{number6} (Free today {number7}/{number8})\n⚡ Power {number9}\n⚔ Sniper Rifle · Rusty Era +{number10}\n📍 Field (best: Zone {number11})", "🎖 Nivel {number1} {number2} / {number3} XP\n💰 {number4} G 🎫 {number5}\n🔑{number6} (Gratis hoy {number7}/{number8})\n⚡ Poder {number9}\n⚔ Rifle de francotirador · Era oxidada +{number10}\n📍 Campo (mejor: Zona {number11})" },
		{ "💰 Not enough gold. ({number1} needed) Earn gold at the dummy yard, field hunting, dungeons, or the Boss Rush", "💰 Oro insuficiente. (se necesitan {number1}) Gana oro en el campo de muñecos, en la caza, en las mazmorras o en el Boss Rush" },
		{ "🥇 {player1}\n<font color='#ffe{number1}e'>⚡ {number2}</font> Lv.{number3}\n<font color='#{number4}ad{number5}ff'>Spell Tome · Mythic Era +{number6}</font>", "🥇 {player1}\n<font color='#ffe{number1}e'>⚡ {number2}</font> Nivel {number3}\n<font color='#{number4}ad{number5}ff'>Tomo de hechizos · Era mítica +{number6}</font>" },
		{ "🎖 Lv.{number1}  {number2} / {number3} XP\n💰 {number4} G   🎫 {number5}\n🔑{number6} (Free today {number7}/{number8})\n⚡ Power {number9}\n⚔ Spell Tome · Rusty Era +{number10}\n📍 Field (best: Zone {number11})", "🎖 Nivel {number1} {number2} / {number3} XP\n💰 {number4} G 🎫 {number5}\n🔑{number6} (Gratis hoy {number7}/{number8})\n⚡ Poder {number9}\n⚔ Tomo de Hechizos · Era Oxidada +{number10}\n📍 Campo (mejor: Zona {number11})" },
		{ "Zone {number1} · Abyss\n🌀 Gate of the Abyss · Rec. ⚡{number2}\nDanger ☠☠☠☠☠☠☠☠\n🌀 New set from here: Abyss Dominion Set", "Zona {number1} · Abismo\n🌀 Puerta del Abismo · Rec. ⚡{number2}\nPeligro ☠☠☠☠☠☠☠☠\n🌀 Nuevo conjunto a partir de aquí: Conjunto de Dominio del Abismo" },
		{ "⚠ The {number1}-hour cap was reached, so {number2} hours' worth couldn't be saved. You can raise the cap in the Shop", "⚠ Se alcanzó el límite de {number1} horas, así que no se pudieron guardar {number2} horas. Puedes subir el límite en la tienda" },
		{ "💰 Not enough gold. ({number1} needed) Earn gold from field hunting, dungeons, the Boss Rush, or idle income", "💰 Oro insuficiente. (se necesitan {number1}) Consigue oro con la caza, las mazmorras, el Boss Rush o los ingresos pasivos" },
		{ "Zone {number1} · Forest\n🏰 Forest Castle Gate · Rec. ⚡{number2}\nDanger ☠☠\n🌲 New set from here: Forest's Blessing Set", "Zona {number1} · Bosque\n🏰 Puerta del castillo del bosque · Recomendado ⚡{number2}\nPeligro ☠☠\n🌲 Nuevo conjunto a partir de aquí: Conjunto de bendición del bosque" },
		{ "Zone {number1} · Snowfield\n❄ Ice Palace Gate · Rec. ⚡{number2}\nDanger ☠☠☠☠☠\n❄ New set from here: Frost's Breath Set", "Zona {number1} · Campo de nieve\n❄ Puerta del Palacio de Hielo · Rec. ⚡{number2}\nPeligro ☠☠☠☠☠\n❄ Nuevo conjunto a partir de aquí: Conjunto de aliento helado" },
		{ "enemies below {number1}% HP are executed · bosses take up to +{number2}% damage (all your damage) as their HP drops", "los enemigos por debajo del {number1}% de salud son ejecutados · los jefes reciben hasta +{number2}% de daño (todo tu daño) conforme baja su salud" },
		{ "Zone {number1} · Desert\n🏜 Desert Temple Entrance · Rec. ⚡{number2}\nDanger ☠☠☠☠\n🏜 New set from here: Desert Sun Set", "Zona {number1} · Desierto\n🏜 Entrada del templo del desierto · Rec. ⚡{number2}\nPeligro ☠☠☠☠\n🏜 Nuevo conjunto desde aquí: Conjunto de sol del desierto" },
		{ "🏔 Hunting Field\n{number1} Meadow · {number2} Forest\n{number3} Wasteland · {number4} Desert\n{number5} Snowfield · {number6} Volcano\n{number7} Darklands · {number8} Abyss", "🏔 Campo de caza\n{number1} Pradera · {number2} Bosque\n{number3} Tierra baldía · {number4} Desierto\n{number5} Campo de nieve · {number6} Volcán\n{number7} Tierras Oscuras · {number8} Abismo" },
		{ "Zone {number1} · Darklands\n🦇 Dark Castle Gate · Rec. ⚡{number2}\nDanger ☠☠☠☠☠☠☠\n🦇 New set from here: Dark Pact Set", "Zona {number1} · Tierras oscuras\n🦇 Puerta del castillo oscuro · Recomendado ⚡{number2}\nPeligro ☠☠☠☠☠☠☠\n🦇 Nuevo conjunto desde aquí: Conjunto de pacto oscuro" },
		{ "Zone {number1} · Volcano\n🌋 Lava Fortress Gate · Rec. ⚡{number2}\nDanger ☠☠☠☠☠☠\n🌋 New set from here: Lava Heart Set", "Zona {number1} · Volcán\n🌋 Puerta de la fortaleza de lava · Rec. ⚡{number2}\nPeligro ☠☠☠☠☠☠\n🌋 Nuevo conjunto a partir de aquí: Conjunto de corazón de lava" },
		{ "🚧 Stuck at level {number1}! Go to Menu (B) → Skills & Growth tab (Passives · Training) to break through.", "🚧 ¡Estancado en el nivel {number1}! Ve al menú (B) → pestaña Habilidades y crecimiento (pasivas · entrenamiento) para superarlo." },
		{ "💰 Not enough Gold. ({number1} needed) Earn Gold from field hunting / dungeons / Boss Rush / idle income", "💰 Oro insuficiente. (se necesitan {number1}) Oro de caza / mazmorras / Boss Rush / ingresos pasivos" },
		{ "Zone {number1} · Meadow\n🌾 Adventure Begins · Rec. ⚡{number2}\nDanger ☠\n🌾 New set from here: Meadow's Guard Set", "Zona {number1} · Pradera\n🌾 La aventura comienza · Rec. ⚡{number2}\nPeligro ☠\n🌾 Nuevo conjunto desde aquí: Conjunto de guardia del prado" },
		{ "Limit Breaker   Title 『Limit Breaker』\nDefeat {number1} bosses in one Boss Rush run\n{number2} / {number3}   Reward: 🎫 {number4}", "Título \"Rompedor de límites\"\nDerrota a {number1} jefes en una partida de carrera de jefes\n{number2} / {number3} Recompensa: 🎫 {number4}" },
		{ "Deadeye: an enemy must be within {number1} range to lock on! (Camps are safe zones with no enemies", "Ojo muerto: ¡debe haber un enemigo a {number1} de distancia para fijarlo! (Los campamentos son zonas seguras sin enemigos" },
		{ "🎖 Lv.{number1}  {number2} / {number3} XP\n💰 {number4} G   🎫 {number5}\n🔑{number6} (Free today {number7}/{number8})\n⚡ Power {number9}\n⚔ Sniper Rifle · Rusty Era +{number10}\n📍 Dungeon", "🎖 Nivel {number1} {number2} / {number3} XP\n💰 {number4} G 🎫 {number5}\n🔑{number6} (Gratis hoy {number7}/{number8})\n⚡ Poder {number9}\n⚔ Rifle de francotirador · Era oxidada +{number10}\n📍 Mazmorra" },
		{ "🌱 Beginner's Boon: +{number1}% damage and -{number2}% damage taken until you clear Zone {number3} (it fades by Lv {number4})", "🌱 Beneficio para principiantes: +{number1}% de daño y -{number2}% de daño recibido hasta que completes la Zona {number3} (desaparece al alcanzar el nivel {number4})" },
		{ "🐾 Pet Lv.{number1}! New ability 🧲 Auto-Loot — Loot within a {number2} radius gets pulled in automatically", "🐾 ¡Mascota de nivel {number1}! Nueva habilidad 🧲 Recogida automática: el botín dentro de un radio de {number2} se recoge automáticamente" },
		{ "Boss Hunter   Title 『Boss Hunter』\nDefeat {number1} bosses in one Boss Rush run\n{number2} / {number3}   Reward: 🎫 {number4}", "Título de cazador de jefes\nDerrota a {number1} jefes en una partida de carrera de jefes\n{number2} / {number3} Recompensa: 🎫 {number4}" },
		{ "Unbreakable   Title 『Unbreakable』\nSurvive {number1} seconds in the Boss Rush\n{number2} / {number3}   Reward: 🎫 {number4}", "Título \"Inquebrantable\"\nSobrevive {number1} segundos en la Oleada de Jefes\n{number2} / {number3} Recompensa: 🎫 {number4}" },
		{ "Reduces training / breakthrough wait time by {number1} min (the skip bar fills instantly)", "Reduce el tiempo de espera de entrenamiento/avance en {number1} minutos (la barra de salto se llena instantáneamente)" },
		{ "🌟 A golden FEVER portal opened where the Colossus fell! Step in within {number1} seconds!", "🌟 ¡Se abrió un portal dorado de FIEBRE donde cayó el Coloso! ¡Entra en {number1} segundos!" },
		{ "Survivor   Title 『Survivor』\nSurvive {number1} seconds in the Boss Rush\n{number2} / {number3}   Reward: 🎫 {number4}", "Título de sobreviviente 『Sobreviviente』\nSobrevive {number1} segundos en la Oleada de Jefes\n{number2} / {number3} Recompensa: 🎫 {number4}" },
		{ "First Dungeon   Title 『Dungeon Newbie』\nClear {number1} dungeon(s)\n{number2} / {number3}   Reward: {number4} G + 🎫 {number5}", "Primer calabozo - Título: \"Novato de mazmorras\"\nCompleta {number1} mazmorras\n{number2} / {number3} Recompensa: {number4} G + 🎫 {number5}" },
		{ "Golden Hunter   Title 『Lucky Hunter』\nDefeat {number1} Golden Goblin(s)\n{number2} / {number3}   Reward: {number4} G", "Título del cazador dorado: \"Cazador afortunado\"\nDerrota a {number1} duendes dorados\n{number2} / {number3} Recompensa: {number4} G" },
